import fs from "node:fs/promises";
import path from "node:path";
import { randomBytes } from "node:crypto";

const root = process.cwd();
const envFile = path.join(root, ".env.docker");
const password = randomBytes(32).toString("hex");
const databaseUrl = `postgresql://elitze:${password}@postgres:5432/elitze`;

await fs.writeFile(
  envFile,
  [
    "# Generated by npm run docker:init. Never commit this file.",
    `ELITZE_POSTGRES_PASSWORD=${password}`,
    `ELITZE_DATABASE_URL=${databaseUrl}`,
    "NEXT_PUBLIC_SITE_URL=http://localhost:3000",
    "ELITZE_BIND_ADDRESS=127.0.0.1",
    "ELITZE_HTTP_PORT=3000",
    "",
  ].join("\n"),
  { mode: 0o600 },
);

console.log("Created .env.docker with a random local PostgreSQL credential.");
console.log("Start the portable stack with:");
console.log("docker compose --env-file .env.docker up --build");
